let dbData = $input.all();
const baseUrl = "https://foto.budi.biz.id/";

if (dbData.length === 0 || Object.keys(dbData[0].json).length === 0) {
    return [{ json: { hasil: "Barang tidak ditemukan di katalog untuk pencarian tersebut. Informasikan ke pengguna secara formal." } }];
}

let hasil_teks = "Referensi dari katalog:\n";

dbData.forEach((row, index) => {
    let item = row.json;
    hasil_teks += (index + 1) + ". Nama: " + (item.judul || "-") + "\n";
    hasil_teks += "   Kode BOM: " + (item.kode_bom || "-") + "\n";
    hasil_teks += "   Tautan Foto: " + (item.imageUrl ? baseUrl + item.imageUrl : "Tidak ada gambar") + "\n\n";
});

return [{ json: { hasil: hasil_teks } }];
